/* prog17_whitespace_trim.c
 *
 * Re‑implementation of the original binary (prog17_whitespace_trim).
 *
 * Behaviour (deduced from the disassembly):
 *   • If no command‑line argument is supplied, prints "EMPTY".
 *   • Takes the first argument (argv[1]) and examines at most the first
 *     0x400 (1024) characters of it.
 *   • Removes leading whitespace, removes trailing whitespace, and collapses
 *     any run of whitespace characters inside the string to a single space.
 *   • Whitespace characters recognised are: space, tab, newline, carriage‑
 *     return, vertical‑tab ('\v'), and form‑feed ('\f').
 *   • If the resulting string is empty, prints "EMPTY".
 *   • Otherwise prints the processed string followed by a newline.
 *
 * The implementation below follows the same logic, but written in clear C.
 */

#include <stdio.h>
#include <string.h>
#include <stdbool.h>

static bool is_my_space(char c)
{
    return c == ' '  || c == '\t' || c == '\n' ||
           c == '\r' || c == '\v' || c == '\f';
}

int main(int argc, char *argv[])
{
    const char *src;
    char out[0x401];                 /* 1024 chars + terminating NUL */
    size_t out_len = 0;
    bool pending_ws = false;        /* we have seen whitespace that may become a single space */
    bool started = false;           /* have we output any non‑whitespace character yet? */

    if (argc < 2) {
        puts("EMPTY");
        return 0;
    }

    src = argv[1];
    size_t src_len = strlen(src);
    if (src_len > 0x400)            /* original program caps the length at 1024 */
        src_len = 0x400;

    for (size_t i = 0; i < src_len; ++i) {
        char c = src[i];

        if (is_my_space(c)) {
            /* Remember that we are in a whitespace run.  A space will be
               emitted only when a non‑whitespace character follows and we
               have already output something (i.e., not leading whitespace). */
            pending_ws = true;
            continue;
        }

        /* c is a non‑whitespace character */
        if (pending_ws && started) {
            out[out_len++] = ' ';    /* collapse the preceding whitespace run */
        }
        /* Leading whitespace (started == false) is simply ignored */

        out[out_len++] = c;
        started = true;
        pending_ws = false;
    }

    out[out_len] = '\0';

    if (out_len == 0) {
        puts("EMPTY");
    } else {
        puts(out);
    }
    return 0;
}
